SELECT COUNT(*) FROM fans f
JOIN engagement e ON f.userregistry = (SELECT memberfanpivot FROM membershipandspending WHERE memberreg = e.engagememberpivot)
WHERE e.actfreq = 'Daily';

-- Check if engagement table has entries not linked to membership
SELECT COUNT(*) FROM engagement e WHERE NOT EXISTS (
  SELECT 1 FROM membershipandspending m WHERE m.memberreg = e.engagememberpivot
);
